"""1358 (#11, pickup_loot_steal): Record-Coverage-v1357.ps1 aiming by the native use focus. In coverage-v1357a both
pickpockets pressed X with nothing focused (the press holstered the sword, Undraw81), Emily's body search missed after her
choke, and two cases failed on a transient --player-inventory read. Now, as in Test-MissionUsable-v1135 (1133, confirmed
runtime: arkCpntPlayerSensorInteraction+0x80 high dword is the focused entity handle), the source sweeps its yaw and pitch
until the focus is the guard's belt key (pickpocket) or the guard's body (bodyloot) before pressing X, and inventory reads
retry. Generated by make_coverage_v1358.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1357.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:100])
    s = s.replace(old, new)

rep("# 1357 (#11):", "# 1358 (#11): loot by the native use focus; inventory reads retry. Generated by make_coverage_v1358.py.\n# 1357 (#11):")
rep("[string]$Take='coverage-v1357a'", "[string]$Take='coverage-v1358a'")
rep("$domAim={param($target,$stand)", """# 1358: the native use focus (1133/1135) and a retrying inventory read.
$script:sensor=@{};$script:byHandle=@{}
function FocusInit($r){$pl=Q $r '--player';$ents=(Q $r '--entities').entities;$me=@($ents|Where-Object pointer -eq $pl.player);if($me.Count-ne1){throw "Player entity not unique $r"}
 $sc=@((Q $r '--components' $me[0].handle).components|Where-Object type -eq '.?AVarkCpntPlayerSensorInteraction@@');if($sc.Count-ne1){throw "Interaction sensor not unique $r"}
 $script:sensor[$r]=$sc[0].pointer;$script:byHandle[$r]=@{};foreach($e in $ents){$script:byHandle[$r][[Convert]::ToUInt32(($e.handle-replace'^0x',''),16)]=$e}}
function Focus($r){$o=Q $r '--object' $script:sensor[$r];$w=@($o.words|Where-Object offset -eq '0x80');if($w.Count-ne1){return $null}
 $h=[uint32]([Convert]::ToUInt64($w[0].word.Substring(2),16)-shr32);$e=$script:byHandle[$r][$h];if(!$e){return [pscustomobject]@{handle=('0x{0:x}'-f$h);name=$null}};[pscustomobject]@{handle=$e.handle;name=$e.name}}
function InvSafe($r){for($a=0;$a-lt8;$a++){try{return @((Q $r '--player-inventory').items|Where-Object {$_.quantity-gt0}|ForEach-Object {"$($_.name)=$($_.quantity)"})}catch{Start-Sleep -Milliseconds 400}};$null}
function SweepFocus($r,$x,$y,$baseYaw,$pitches,$pattern){$tr=[Collections.Generic.List[object]]::new()
 foreach($pt in $pitches){foreach($off in 0,-12,12,-24,24){C $r ('setviewpos {0} {1} 68.1 {2} 0' -f (F $x),(F $y),(F ($baseYaw+$off)));& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $r -Pitch $pt -Quick|Out-Null;Start-Sleep -Milliseconds 200
  $f=Focus $r;$tr.Add([pscustomobject]@{pitch=$pt;yaw=$baseYaw+$off;focus=$(if($f){$f.name}else{$null})});if($f-and$f.name-and$f.name-match$pattern){return [pscustomobject]@{found=$true;trials=@($tr);focus=$f.name}}}}
 [pscustomobject]@{found=$false;trials=@($tr);focus=$null}}
$domAim={param($target,$stand)""")
rep("""    $row.itemsBefore=@((Q $source '--player-inventory').items|Where-Object {$_.quantity-gt0}|ForEach-Object {"$($_.name)=$($_.quantity)"})""",
    """    $row.itemsBefore=InvSafe $source;FocusInit $source""")
rep("""    C $source ('setviewpos {0} {1} 68.1 {2} 0' -f (F $sx),(F $sy),(F $syaw));& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch $(if($case-eq'pickpocket'){20}else{0}) -Quick|Out-Null""",
    """    C $source ('setviewpos {0} {1} 68.1 {2} 0' -f (F $sx),(F $sy),(F $syaw));& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 0 -Quick|Out-Null;$script:lootStand=@($sx,$sy,$syaw)
    if($case-eq'pickpocket'){$sw=SweepFocus $source $sx $sy $syaw @(4,10,16,22,28) '(?i)key|pouch|coin';$row.focusTrials=$sw.trials;$row.focus=$sw.focus;if(!$sw.found){throw "No pickpocket focus on the guard (last $(@($sw.trials)[-1].focus))"}}""")
rep("""     elseif($step-eq1-and$t-ge8600){& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 50 -Quick|Out-Null;$step=2}""",
    """     elseif($step-eq1-and$t-ge8600){$bg=@((Q $source '--world-npcs').npcs|Where-Object {$_.spawnerName-eq'ld_spawner_guard_tutorial_2'});$me=(Q $source '--player').candidatePosition
      $byaw=if($bg.Count){[Math]::Atan2([double]$bg[0].position[1]-[double]$me[1],[double]$bg[0].position[0]-[double]$me[0])*180/[Math]::PI}else{$script:lootStand[2]}
      $sw=SweepFocus $source $me[0] $me[1] $byaw @(35,45,55,65) '(?i)guard|tutorial';$row.focusTrials=$sw.trials;$row.focus=$sw.focus;$step=2}""")
rep("""     $row.itemsAfter=@((Q $source '--player-inventory').items|Where-Object {$_.quantity-gt0}|ForEach-Object {"$($_.name)=$($_.quantity)"})
     $row.gained=@($row.itemsAfter|Where-Object {$_-notin$row.itemsBefore})""",
    """     $row.itemsAfter=InvSafe $source;$row.gained=if($row.itemsAfter-and$row.itemsBefore){@($row.itemsAfter|Where-Object {$_-notin$row.itemsBefore})}else{@()}""")
rep("if($case-eq'pickpocket'-and!$row.gained.Count){throw 'The pickpocket gained no item'}", "if($case-eq'pickpocket'-and$row.itemsAfter-and!$row.gained.Count){throw 'The pickpocket gained no item'}")
rep("""     if($step-eq0-and$t-ge900){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='pickpocket'});$step=1}}""",
    """     if($step-eq0-and$t-ge900){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='pickpocket'});$step=1}
     elseif($step-eq1-and$t-ge2600-and!@($samples|Where-Object {$_.active -contains 47}).Count){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='pickpocket again'});$step=2}}""")
rep("pickpocket=6500;bodyloot=13500;", "pickpocket=7500;bodyloot=22000;")
rep("""     elseif($step-eq2-and$t-ge9300){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='search body'});$step=3}
     elseif($step-eq3-and$t-ge10800-and""", """     elseif($step-eq2){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='search body'});$script:xAt=$t;$step=3}
     elseif($step-eq3-and$t-ge$script:xAt+1500-and""")
rep("scope='Pickpocket and body loot on the standing tutorial guard (1357, #11)", "scope='Pickpocket and body loot by the native use focus (1358, #11), on the standing tutorial guard (1357)")
